    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(b - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">7</span></span>) - (b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>) = -<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">7</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"يختفي المجهول","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">7</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> = -<span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">14</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">14</span></span> < 0</span>"},{"quoi":"القاعدة","math":"الفرق سالب، إذن العبارة الأولى أصغر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">7</span></span> < b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(b + 0) - (b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span>) = 0 - (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"يختفي المجهول","math":"<span dir=\"ltr\" class=\"expr\">0 - (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span>) = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> > 0</span>"},{"quoi":"القاعدة","math":"الفرق موجب، إذن العبارة الأولى أكبر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b + 0 > b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(b + 7) - (b + 1) = 7 - 1</span>"},{"quoi":"يختفي المجهول","math":"<span dir=\"ltr\" class=\"expr\">7 - 1 = 6</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">6 > 0</span>"},{"quoi":"القاعدة","math":"الفرق موجب، إذن العبارة الأولى أكبر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b + 7 > b + 1</span>"}],
