    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">2 + ((-7) + a) = a - 5</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">3 - [-4 - (a - 2)] = a + 5</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(a - 5) - (a + 5) = -10</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-10 < 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a - 5 < a + 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">9 + (4 + a) = a + 13</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">-2 - [-8 - (a - 0)] = a + 6</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(a + 13) - (a + 6) = 7</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">7 > 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a + 13 > a + 6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">-4 + (0 + x) = x - 4</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">4 - [5 - (x - -9)] = x + 8</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x - 4) - (x + 8) = -12</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-12 < 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x - 4 < x + 8</span>"}],
